import * as T from 'three';
// Recovered centre positions come from actual native51/84/89 planar sections.
// Body/pin dimensions are an authored functional reference for a push rivet,
// not a supplier SKU or a reconstructed manufacturer solid.
import {CHAMBER_RIVETS} from './chamber-service-datums.js';
export {CHAMBER_RIVETS};
const smooth=t=>{t=T.MathUtils.clamp(t,0,1);return t*t*(3-2*t);};
export class ChamberRivet{
 constructor(def,owner){this.id=def.id;this.def=def;this.owner=owner;const body=new T.LatheGeometry([[.76,-5.5],[1.48,-5.5],[1.48,0],[3,0],[3,.8],[.76,.8],[.76,-5.5]].map(p=>new T.Vector2(...p)),20),pin=new T.CylinderGeometry(.7,.7,6,12),cap=new T.CylinderGeometry(2,2,.7,16);pin.translate(0,-1.9,0);cap.translate(0,1.45,0);const pieces=[body,pin,cap].map(g=>g.index?g.toNonIndexed():g),p=new Float32Array(pieces.reduce((n,g)=>n+g.attributes.position.array.length,0)),normal=new Float32Array(p.length);let at=0;for(const g of pieces){p.set(g.attributes.position.array,at);normal.set(g.attributes.normal.array,at);at+=g.attributes.position.array.length;}this.pinStart=pieces[0].attributes.position.count;pieces.forEach(g=>g.dispose());[body,pin,cap].forEach(g=>g.dispose());this.original=p;this.baseNormal=normal;this.geometry=new T.BufferGeometry();this.geometry.setAttribute('position',new T.BufferAttribute(p.slice(),3));this.geometry.setAttribute('normal',new T.BufferAttribute(normal.slice(),3));const m=new T.MeshStandardMaterial({color:'#24272a',roughness:.8});m.userData.originalColor=m.color.clone();m.userData.originalOpacity=1;this.mesh=new T.Mesh(this.geometry,m);this.mesh.userData={part:this.id,component:this.id,flexId:this.id,serviceTask:'chamber-fan',cadName:'Push rivet · authored functional reference',sourceNativeHole:def.native,reference:true,qualification:'3.2 mm source hole; inferred push-rivet body/pin dimensions; not supplier CAD'};this.curve=new T.LineCurve3(new T.Vector3(),new T.Vector3(0,.001,0));this.write(1);}
 update(from,to,t){if(this.update!==ChamberRivet.prototype.update||!this.owner.active||this.owner.viewer.chamberServiceOwner!==this.owner||!this.owner.enabled||this.owner.viewer.fasteners.entities.get(this.id)!==this||this.mesh.geometry!==this.geometry)return;this.write(T.MathUtils.lerp(from,to,smooth(t)));}
 write(amount){const q=1-amount,body=18*smooth((q-.2)/.8),pin=3*smooth(q/.2),rotation=new T.Quaternion().setFromUnitVectors(new T.Vector3(0,1,0),new T.Vector3(...this.def.axis)),p=new T.Vector3(),n=new T.Vector3(),pos=this.geometry.attributes.position,normal=this.geometry.attributes.normal;for(let i=0;i<pos.count;i++){p.fromArray(this.original,i*3);p.y+=body+(i>=this.pinStart?pin:0);p.applyQuaternion(rotation).add(new T.Vector3(...this.def.p)).multiplyScalar(.001);pos.setXYZ(i,p.x,p.y,p.z);n.fromArray(this.baseNormal,i*3).applyQuaternion(rotation);normal.setXYZ(i,n.x,n.y,n.z);}pos.needsUpdate=true;normal.needsUpdate=true;this.geometry.computeBoundingBox();this.geometry.computeBoundingSphere();this.mesh.userData.flexState={amount,pinRelease:pin,bodyWithdrawal:body};}
 guide(to=1,from=0){if(this.guide!==ChamberRivet.prototype.guide||!this.owner.active||!this.owner.enabled||this.owner.viewer.chamberServiceOwner!==this.owner||this.owner.viewer.fasteners.entities.get(this.id)!==this||this.mesh.geometry!==this.geometry)return[];return [from,to].map(a=>new T.Vector3(...this.def.p).addScaledVector(new T.Vector3(...this.def.axis),18*(1-a)).multiplyScalar(.001));}
}
